    ("i1", "A room says a hundred ninety nine dollars. Why do you pay two hundred thirty eight?", 1.02, 0.35, +1.0, 1.45, ['ninety', 'thirty', 'pay'], None),
    ("i2", "You're booking a weekend away. Then you spot thirty nine dollars a day, called a resort fee.", 1.04, 0.2, +0.8, 1.45, ['weekend', 'thirty', 'resort'], "low"),
    ("i3", "Those are made-up numbers from America's consumer regulator. Hotels say the fee covers things like Wi-Fi and the gym. Use them or not, you pay.", 1.04, 0.25, +0.6, 1.45, ['made-up', 'gym.', 'pay.:dn'], "low"),
